```jsx
import React from 'react'
import ReactDOM from 'react-dom'
import {
  SchemaForm,
  Field,
  FormButtonGroup,
  Submit,
  Reset,
  filterChanged,
  createFormActions
} from '@uform/next'
import { Button } from '@alifd/next'
import '@alifd/next/dist/next.css'
import Printer from '@uform/printer'

const actions = createFormActions()

const sleep = duration =>
  new Promise(resolve => {
    setTimeout(resolve, duration)
  })

ReactDOM.render(
  <Printer>
    <SchemaForm
      onSubmit={v => console.log(v)}
      actions={actions}
      labelCol={7}
      wrapperCol={12}
      effects={($, { setFieldState, hasChanged }) => {
        $('onFormMount').subscribe(() => {
          setFieldState('radio', state => {
            state.required = true
          })
        })

        $('onFormChange').subscribe(async state => {
          if (hasChanged(state, 'values.hello')) {
            await sleep(1000)
            setFieldState('radio', state => {
              state.value = '4'
            })
          }
        })
      }}
    >
      <Field
        type="radio"
        enum={['1', '2', '3', '4']}
        title="Radio"
        name="radio"
      />
      <Field
        type="string"
        enum={['1', '2', '3', '4']}
        required
        title="Select"
        name="select"
      />
      <Field
        type="checkbox"
        enum={['1', '2', '3', '4']}
        required
        title="Checkbox"
        name="checkbox"
      />
      <Field
        type="string"
        title="TextArea"
        name="textarea"
        x-component="textarea"
        x-rules={value => {
          return value > 20
            ? {
                type: 'warning',
                message: '这是个警告信息'
              }
            : ''
        }}
      />
      <Field type="number" title="数字选择" name="number" />
      <Field type="boolean" title="开关选择" name="boolean" />
      <Field type="date" title="日期选择" name="date" />
      <Field
        type="daterange"
        title="日期范围"
        default={['2018-12-19', '2018-12-19']}
        name="daterange"
      />
      <Field type="year" title="年份" name="year" />
      <Field type="time" title="时间" name="time" />
      <Field
        type="upload"
        title="卡片上传文件"
        name="upload"
        x-props={{ listType: 'card' }}
      />
      <Field
        type="upload"
        title="拖拽上传文件"
        name="upload2"
        x-props={{ listType: 'dragger' }}
      />
      <Field
        type="upload"
        title="普通上传文件"
        name="upload3"
        x-props={{ listType: 'text' }}
      />
      <Field
        type="range"
        title="范围选择"
        name="range"
        x-props={{ min: 0, max: 1024, marks: [0, 1024] }}
      />
      <Field
        type="transfer"
        enum={[
          { value: 1, label: '选项1' },
          { value: 2, label: '选项2' }
        ]}
        title="穿梭框"
        name="transfer"
      />
      <Field type="rating" title="等级" name="rating" />
      <FormButtonGroup offset={7} sticky>
        <Submit />
        <Reset />
        <Button
          onClick={() => {
            actions.setFieldState('upload', state => {
              state.value = [
                {
                  downloadURL:
                    '//img.alicdn.com/tfs/TB1n8jfr1uSBuNjy1XcXXcYjFXa-200-200.png',
                  imgURL:
                    '//img.alicdn.com/tfs/TB1n8jfr1uSBuNjy1XcXXcYjFXa-200-200.png',
                  name: 'doc.svg'
                }
              ]
            })
          }}
        >
          上传文件
        </Button>
        <Button
          onClick={() => {
            actions.setFormState(state => {
              state.values = {
                radio: '4',
                checkbox: ['2', '3']
              }
            })
          }}
        >
          改变radio的值
        </Button>
        <Button
          onClick={() => {
            actions.setFormState(state => {
              state.values = { ...state.values, hello: 'hello world' }
            })
          }}
        >
          改变form状态
        </Button>
      </FormButtonGroup>
    </SchemaForm>
  </Printer>,
  document.getElementById('root')
)
```
