## 项目推荐
- 项目地址：
https://github.com/concentjs/concent

- 文档地址：
https://concentjs.github.io/concent-doc/

- 类别：JS

- 项目后续更新计划：
核心功能和api已近稳定，后续注重于concli的开发，让用户可以快速生成concent的js & ts应用标准骨架项目

- 项目描述：
一个可预测、0入侵、渐进式、高性能的react增强型状态管理方案，基于依赖标记、引用收集和状态分发原理工作，让状态管理遁于无形，内置computed、watch、setup等高级特性，且对类组件和函数组件暴露100%一致的调用方式，抹平两者之间生命周期函数写法差异，这意味着不仅组件的逻辑复用更优雅，组件的表现形式也更将自由。

- 推荐理由：可预测、0入侵、渐进式、高性能、增强react组件能力、对ts友好、支持中间件和插件、兼容redux生态。

- 示例代码：
```js
import React, { Component, Fragment } from "react";
import { register, run, useConcent } from "concent";

run({
  counter: {// 定义counter模块
    state: {// 【必需】，定义state
      count: 0
    },
    reducer: {// 【可选】定义reducer，书写修改模块状态逻辑
      inc(payload = 1, moduleState) {
        return { count: moduleState.count + payload };
      }
    }
  }
});

class Counter extends Component {
  //setState 能够将数据将同步到store，广播到其他实例
  inc = () => {
    this.setState({ count: this.state.count + 1 });
  };
  //调用dispatch, 同样的能够将数据将同步到store，广播到其他属于counter模块或者连接到counter模块的实例
  incD = () => {
    this.ctx.dispatch("inc"); // or this.ctx.moduleReducer.inc()
  };
  render() {
    //concent注入counter模块的数据到state
    const { count } = this.state;
    return (
      <div style={{ padding: "12px", margin: "6px" }}>
        <div>count: {count}</div>
        <button onClick={this.inc}>inc by setState</button>
        <button onClick={this.incD}>inc by dispatch</button>
      </div>
    );
  }
}
//将Counter类注册为CcClazzCounter，属于counter模块
const CcClazzCounter = register("counter")(Counter);

// 抽到setup，setup函数只会在组件初次渲染前被调用一次！！！
const setup = ctx => {
  ctx.on('someEvent', (p1, p2)=>console.log(p1, p2));

  ctx.effect(() => {
    fetchProducts();
  }, ["type", "sex", "addr", "keyword"]);//这里只需要传key名称就可以了
   /** 对应useEffect, componentDidUpdate */

  ctx.effect(() => {
    return () => {
      // 返回一个清理函数
      // 等价于useEffect, componentWillUnmout, 这里搞清理事情
    };
  }, []);

  inc = () => ctx.setState({ count: this.state.count + 1 });
  incD = () => ctx.dispatch("inc");
  //incD = () => ctx.moduleReducer.inc(); // 这样写更优雅
  return { inc, incD }; //返回结果收集到settings里
};

// 装配到类组件
const SetupCounter = register({ module: "counter", setup })(
  class extends Component {
    render() {
      const { count } = this.state;
      const { inc, incD } = this.ctx.settings;
      // 绑定 count  inc incD 到视图, return ui
    }
  }
);

// 装配到函数组件
const SetupCounterFn = React.memo(function() {
  const {
    state,
    settings: { inc, incD }; //api 只需要定义一次，不存在每次渲染都创建临时闭包函数了
  } = useConcent({ module: "counter", setup });
  // 绑定 count  inc incD 到视图, return ui
});

```
