- 项目描述：
  - 必写：ginrpc 是gin框架中间件(已经被gin官方收录)，用于自动参数绑定及自动路由注册
 - 支持对象自动注册及注解路由
 - 支持参数自动绑定
 - 自带请求参数过滤及绑定实现 binding:"required" validator

- 推荐理由：类似于rpc框架，不用每次函数调用都要写很多代码来绑定参数。也不用路由注册。直接自动注册到地址映射

- 示例代码：
```
package main

import (
	"fmt"
	"net/http"

	_ "ginweb/routers" // debug模式需要添加[mod]/routers 注册注解路由

	"github.com/gin-gonic/gin"
	"github.com/xxjwxc/ginrpc"
	"github.com/xxjwxc/ginrpc/api"
)

type ReqTest struct {
	AccessToken string `json:"access_token"`
	UserName    string `json:"user_name" binding:"required"` // 带校验方式
	Password    string `json:"password"`
}

type Hello struct {
}

// Hello 带注解路由(参考beego形式)
// @router /block [post,get]
func (s *Hello) Hello(c *api.Context, req *ReqTest) {
	fmt.Println(req)
	c.WriteJSON(req) // 返回结果
}

// Hello2 不带注解路由(参数为2默认post)
func (s *Hello) Hello2(c *gin.Context, req ReqTest) {
	fmt.Println(req)
	c.JSON(http.StatusOK, "ok") // gin 默认返回结果
}

func main() {
	base := ginrpc.New(ginrpc.WithGroup("xxjwxc"))
	router := gin.Default()
	base.Register(router, new(Hello)) // 对象注册 like(go-micro)
	router.Run(":8080")
}
```

