// 词法分析器
let lexer = {
    // 有限状态自动机 deterministic finite automaton
    DFA: {
        result: {
            matchs: [], // 已匹配的字符队列
            tokens: [], // 已生成的token列表
        },
        state: DFA_STATE_CONST.S_RESET, // 当前机器的状态
        events: {
            flowtoNextState(ch, state) {
                lexer.DFA.resultChange.pushToMatchs(ch);
                lexer.DFA.state = state;
