- 示例代码：（可选）
```c
#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include "db.h"

#define COUNT 100000L
#define PATH "./db_test"

int main(){
    db_t* db;
    int i,rc;
    char value[128];

    // 创建数据库
    unlink(PATH);
    db_create(PATH,DB_INT32KEY,sizeof(int));

    // 打开数据库
    db_open(&db,PATH);

    // 插入操作
    for(i=0;i<COUNT;i++){
        sprintf(value,"%d",i);
        db_insert(db,&i,value,strlen(value));
    }

    //查询操作
    i = 0;
    bzero(value,sizeof(value));
    rc = db_search(db,&i,value,sizeof(value));
    printf("search key: %d value: %.*s\n",i,rc,value);

    // 关闭数据库
    db_close(db);

    return 0;
}
```

