## 示例代码

#### C
```c
#include "pocketpy.h"

int main(){
    // 创建一个虚拟机
    VM* vm = pkpy_new_vm(true);
    
    // Hello world!
    pkpy_vm_exec(vm, "print('Hello world!')");

    // 构建一个列表
    pkpy_vm_exec(vm, "a = [1, 2, 3]");

    // 对列表进行求和
    char* result = pkpy_vm_eval(vm, "sum(a)");
    printf("%s", result);   // 6

    // 释放资源
    pkpy_delete(result);
    pkpy_delete(vm);
    return 0;
}
```

#### C++
```cpp
#include "pocketpy.h"

int main(){
    auto vm = pkpy::make_shared<VM>(true);
    vm->exec("print('Hello world!')", "main.py", EXEC_MODE);
    vm->exec("a = [1, 2, 3]", "main.py", EXEC_MODE);
    PyVar result = vm->exec("sum(a)", "<eval>", EVAL_MODE);
    std::cout << vm->PyInt_AS_C(result);   // 6
    return 0;
}
```

